{"kind":"tool","id":"jClqdQhvn_0","toolName":"write_file","input":{"path":".tmp/crawl.mjs","instructions":"Crawl every site + portal GET route on the dev server, collect internal links, verify each returns 200, report failures","content":"const BASE = process.env.BASE || "http://localhost:3001";
const seeds = [
  "/", "/about", "/impact", "/chapters", "/news", "/events", "/gallery",
  "/partners", "/pathway", "/join", "/start-a-chapter", "/contact",
  "/leading-at-27", "/privacy", "/terms", "/search", "/alumni",
  "/portal", "/portal/login", "/portal/forgot-password", "/portal/activate",
  "/portal/reset-password",
];

const queue = [...seeds];
const seen = new Set();
const broken = [];
const redirects = [];
const missingMeta = [];
const noH1 = [];

async function fetchPage(path) {
  try {
    const res = await fetch(BASE + path, { redirect: "follow" });
    const text = res.status === 200 ? await res.text() : "";
    return { res, text };
  } catch (e) {
    return { res: null, text: "" };
  }
}

while (queue.length) {
  const path = queue.shift();
  if (seen.has(path)) continue;
  seen.add(path);
  const { res, text } = await fetchPage(path);
  if (!res) { broken.push([path, "network error"]); continue; }
  if (res.status !== 200) { broken.push([path, `status ${res.status}`]); continue; }
  if (res.url && new URL(res.url).pathname !== path && path !== "/" && !/^\/(portal|news|chapters)/.test(path)) {
    // soft note only, do not refetch away
  }
  // H1 + title presence
  const h1 = /<h1[ >]/.test(text);
  const title = /<title>[^<]/.test(text);
  if (!h1) noH1.push(path);
  if (!title) missingMeta.push(path);

  // collect internal links
  const hrefs = [...text.matchAll(/href="(\/[^"']*)"/g)].map(m => m[1].split("?")[0].split("#")[0]);
  for (const href of hrefs) {
    if (!seen.has(href) && !href.startsWith("//") && !/\.(png|jpe?g|svg|ico|webp|css|js|txt)$/.test(href)) {
      queue.push(href);
    }
  }
}

const list = [...seen].sort();
for (const path of list) {
  const { res } = await fetchPage(path);
  if (res && res.status !== 200) (res.status < 500 ? broken : broken).push([path, `recheck ${res.status}`]);
}

console.log(JSON.stringify({ checked: seen.size, broken, missingH1: noH1, missingTitle: missingMeta }, null, 2));
"}}


