+import "server-only";
+
+import Redis from "ioredis";
+
+/**
+ * Shared Redis (Upstash) client.
+ *
+ * Enabled only when both `REDIS_ENABLED=true` and `REDIS_URL` are present, so
+ * an instance without the service falls back silently to the in-memory
+ * limiters. The client is created lazily on first use and reused for the
+ * process lifetime. Upstash's TCP endpoint serves TLS even when the URL is
+ * written with a plain `redis://` scheme, so the TLS option is enforced for
+ * that provider and skipped for local dev URLs.
+ */
+let client: Redis | null = null;
+let disabled = false;
+
+export function getRedis(): Redis | null {
+  if (disabled || process.env.REDIS_ENABLED !== "true") return null;
+
+  const url = process.env.REDIS_URL;
+  if (!url) return null;
+
+  if (client) return client;
+
+  try {
+    const isLocal = /^(redis(s)?:\/\/)(localhost|127\.0\.0\.1)/.test(url);
+    client = new Redis(url, {
+      // A limiter must never stall an action on Redis latency: one retry at
+      // most, then fall back to in-memory.
+      maxRetriesPerRequest: 1,
+      enableOfflineQueue: false,
+      connectTimeout: 5000,
+      retryStrategy: (times) => (times > 2 ? null : Math.min(times * 200, 800)),
+      ...(isLocal ? {} : { tls: {} }),
+    });
+    client.on("error", () => {
+      // Connection-level failures degrade to the in-memory limiter below;
+      // the ioredis default would otherwise crash the process on a blip.
+    });
+    return client;
+  } catch {
+    disabled = true;
+    return null;
+  }
+}
