/* ── Cinematic scroll experience ───────────────────────────────────────
   Shared vocabulary for the homepage's scroll-directed story: the pinned
   programmes scene, the chapter network band, and editorial photo
   treatments. Everything degrades to its resting composition when JS is
   unavailable or when the visitor prefers reduced motion. */

/* Programmes: the pinned scene's slow Ken Burns so a held frame still
   breathes while the story scrolls past it. */
@keyframes programme-ken {
  from { transform: scale(1.06); }
  to { transform: scale(1.16) translate(-1.5%, -1%); }
}
.programme-ken {
  animation: programme-ken 14s ease-in-out infinite alternate;
}

/* The scene title swaps with a small rise; key on the element to re-run. */
@keyframes scene-title-in {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}
.scene-title-in {
  animation: scene-title-in 0.6s cubic-bezier(0.22, 0.9, 0.3, 1) both;
}

/* ── Chapter network band ────────────────────────────────────────── */
.net-band .net-link {
  stroke-dasharray: 1.1;
  /* Long dash pattern normalised per-path via pathLength. */
  stroke-dashoffset: 1.1;
  opacity: 0;
  transition: none;
}
.net-band.net-drawn .net-link {
  animation: net-draw 1.4s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  animation-delay: var(--net-delay, 0s);
}
@keyframes net-draw {
  from { stroke-dashoffset: 1.1; opacity: 0; }
  15% { opacity: 1; }
  to { stroke-dashoffset: 0; opacity: 1; }
}
.net-band .net-node,
.net-band .net-hub {
  opacity: 0;
}
.net-band.net-drawn .net-node {
  animation: net-node-in 0.7s cubic-bezier(0.22, 0.9, 0.3, 1) forwards;
  animation-delay: var(--net-node-delay, 0s);
}
.net-band.net-drawn .net-hub {
  animation: net-node-in 0.7s cubic-bezier(0.22, 0.9, 0.3, 1) both;
}
@keyframes net-node-in {
  from { opacity: 0; transform: scale(0.6); }
  to { opacity: 1; transform: scale(1); }
}
.net-node {
  cursor: pointer;
  transform-box: fill-box;
  transform-origin: center;
}
.net-node__dot {
  fill: var(--color-gold-400);
  stroke: rgba(5, 36, 94, 0.9);
